const rehypeVueSfc = (options) => {
  const {
    hoistStyle = true,
    hoistScript = true
  } = options || {};
  return (root) => {
    const pres = [];
    const posts = [];
    const template = {
      type: "element",
      tagName: "template",
      properties: {},
      children: [],
      content: {
        type: "root",
        children: root.children.filter((node) => {
          if (hoistStyle && node.type === "element" && node.tagName === "style") {
            posts.push(node);
            return false;
          }
          if (hoistScript && node.type === "element" && node.tagName === "script") {
            pres.push(node);
            return false;
          }
          return true;
        })
      }
    };
    root.children = [
      ...pres,
      template,
      ...posts
    ];
    return root;
  };
};

export { rehypeVueSfc as default };
